referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const walk = (s, v, p) => {
    if (v === undefined) return s.optional ? [] : [p];
    if (s.type === "object") {
      if (v === null || typeof v !== "object" || Array.isArray(v)) return [p];
      return Object.keys(s.fields).flatMap((k) => walk(s.fields[k], v[k], p + "." + k));
    }
    if (s.type === "array") {
      if (!Array.isArray(v)) return [p];
      return v.flatMap((x, i) => walk(s.items, x, p + "." + i));
    }
    return (s.type === "integer" ? Number.isSafeInteger(v) : typeof v === s.type) ? [] : [p];
  };
  return walk(d.schema, d.value, "$");
}

